// tools/sig/job/post.ts
var POST_PICTURES = { counter: [760, 200], buy: [372, 88], join: [372, 88], board: [760, 0] };
var num = (n) => n.toLocaleString("en-US");
var money = (n) => "$" + num(Math.round(n));
var tct = (at) => new Date(at * 1e3).toISOString().slice(11, 16);
var MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
var when = (at, nowS) => {
  if (Math.floor(at / 86400) === Math.floor(nowS / 86400)) return tct(at);
  const d = new Date(at * 1e3);
  return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]}`;
};
var esc = (s) => s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
var MARK = `<svg width="30" height="30" viewBox="0 0 28 28"><circle cx="14" cy="14" r="12.7" fill="none" stroke="#d94a3d" stroke-width="2.6"/><circle cx="14" cy="14" r="7.2" fill="none" stroke="#d94a3d" stroke-width="2.6"/><circle cx="14" cy="14" r="3.4" fill="#d94a3d"/></svg>`;
var ARROW = `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg>`;
var CSS = `
:root{--field:#080809;--panel:#141415;--raise:#1c1c1e;--line2:#323235;--line3:#3f3f43;--edge:#2a2a2d;
  --ink:#ececec;--mute:#939396;--faint:#5d5d61;--accent:#d94a3d;--green:#7cc96f;--on-green:#0b1309}
*{box-sizing:border-box}html,body{margin:0;background:transparent}
body{padding:8px;display:flex;flex-direction:column;align-items:flex-start;gap:8px}
.img{position:relative;background:var(--panel);border:1px solid var(--edge);border-radius:12px;overflow:hidden;font-family:Manrope,sans-serif;color:var(--ink);font-variant-numeric:tabular-nums}
.rings{position:absolute;inset:0;background:repeating-radial-gradient(circle at 39px 44px,transparent 0 30px,rgba(255,255,255,.05) 30px 31px);-webkit-mask-image:radial-gradient(circle at 39px 44px,#000 0,transparent 62%)}
.wm{display:inline-flex;flex-direction:column;line-height:.9;white-space:nowrap}
.wm i{font:800 9px/1 Manrope;font-style:normal;color:var(--ink);margin-bottom:2px}
.wm b{font-family:Archivo,Manrope;font-weight:900;font-stretch:125%;font-size:19px;letter-spacing:.01em;color:transparent;-webkit-text-stroke:1px var(--ink)}
.cap{font:700 10px/1 Manrope;letter-spacing:.12em;text-transform:uppercase;color:var(--mute)}
#counter{width:760px;height:200px}
#counter .top{position:absolute;left:24px;right:24px;top:16px;height:56px;display:flex;align-items:center;gap:12px}
#counter .sl{margin-left:auto;font:800 15px Manrope;letter-spacing:-.01em}
#counter .rule{position:absolute;left:0;right:0;top:96px;height:1px;background:var(--edge)}
#counter .figs{position:absolute;left:24px;right:24px;top:112px;display:grid;grid-template-columns:1.5fr 1fr 1fr;column-gap:24px}
.fig .n{font:800 40px/1 Manrope;letter-spacing:-.02em;margin:8px 0 0}
.fig.sm .n{font-size:28px;line-height:40px}
.fig .dbl{height:4px;margin-top:8px;border-top:1px solid var(--line3);border-bottom:1px solid var(--line3)}
.fig+.fig{padding-left:24px;border-left:1px solid var(--edge)}
.act{width:372px;height:88px;border-radius:12px;display:flex;flex-direction:column;justify-content:center;gap:6px;padding:0 24px;font-family:Manrope,sans-serif;border:1px solid var(--edge)}
.act .an{display:flex;align-items:center;gap:10px;font:800 21px/1 Manrope}
.act .as{font:600 13px/1 Manrope}
#buy{background:var(--green);color:var(--on-green);border-color:var(--green)}#buy .as{color:rgba(11,19,9,.72)}
#join{background:var(--raise);color:var(--ink)}#join .as{color:var(--mute)}#join .as b{color:var(--green)}
#board{width:760px}
#board .hd{height:56px;display:flex;align-items:center;padding:0 24px;border-bottom:1px solid var(--edge)}
#board h3{margin:0;font:800 18px Manrope;letter-spacing:-.01em}
#board .wk{margin-left:auto;font:600 12px Manrope;color:var(--mute)}
#board .cols{display:grid;grid-template-columns:1fr 1fr;padding:0 24px 8px}#board .cols.one{grid-template-columns:1fr}
#board .cols:not(.one) .col:first-child{padding-right:24px}#board .col+.col{border-left:1px solid var(--edge);padding-left:23px}
#board table{width:100%;border-collapse:collapse;font-size:12px;table-layout:fixed}
#board th{height:32px;text-align:left;font:700 10px Manrope;letter-spacing:.12em;color:var(--faint);border-bottom:2px solid var(--line2);padding:0}
#board td{height:20px;padding:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;border-bottom:1px solid #1b1b1d}
#board tr:last-child td{border-bottom:0}
#board .t{width:44px;color:var(--mute);font-weight:500}
#board .w{font-weight:600}
#board .c{text-align:right;color:var(--mute);font-weight:500}
#board .r{text-align:right;font-weight:600}
#board .none{padding:16px 0;font:500 13px Manrope;color:var(--faint)}
#board .ft{margin:0 24px;height:44px;display:flex;align-items:center;justify-content:flex-end;border-top:1px solid var(--edge);font:500 12px Manrope;color:var(--faint)}
`;
function postPage(s, t, nowS) {
  const rows = s.board.slice(0, 50);
  const col = (part) => `<table><colgroup><col style="width:52px"><col><col style="width:80px"><col style="width:96px"></colgroup><tr><th>WHEN</th><th>TARGET</th><th class="c">BOUNTIES</th><th class="r">REWARD</th></tr>` + part.map((r) => `<tr><td class="t">${when(r.at, nowS)}</td><td class="w">${esc(r.target)}</td><td class="c">${num(r.n)}</td><td class="r">${money(r.reward)}</td></tr>`).join("") + `</table>`;
  const cols = rows.length === 0 ? `<div class="none">None lately</div>` : `<div class="col">${col(rows.slice(0, 25))}</div>${rows.length > 25 ? `<div class="col">${col(rows.slice(25))}</div>` : ""}`;
  return `<!DOCTYPE html><html><head><meta charset="utf-8">
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@125,900&family=Manrope:wght@500;600;700;800&display=block" rel="stylesheet">
<style>${CSS}</style></head><body>
<div class="img" id="counter"><div class="rings"></div>
  <div class="top">${MARK}<span class="wm"><i>the</i><b>COMPANY</b></span><span class="sl">Stay anonymous with us.</span></div>
  <div class="rule"></div>
  <div class="figs">
    <div class="fig"><div class="cap">Bounties placed</div><div class="n">${num(s.placedTotal)}</div><div class="dbl"></div></div>
    <div class="fig sm"><div class="cap">This week</div><div class="n">${num(s.placedWeek)}</div><div class="dbl"></div></div>
    <div class="fig sm"><div class="cap">On the board now</div><div class="n">${num(s.activeJobs)}</div><div class="dbl"></div></div>
  </div>
</div>
<div class="act" id="buy"><span class="an">Buy bounties${ARROW}</span><span class="as">Pay in Xanax \xB7 stay anonymous</span></div>
<div class="act" id="join"><span class="an">Become an associate</span><span class="as">Earn <b>${money(t.associateCut)}\u2013${money(t.associateCutAnon)}</b> a bounty</span></div>
<div class="img" id="board">
  <div class="hd"><h3>Latest bounties</h3><span class="wk">${num(s.placedWeek)} this week</span></div>
  <div class="cols${rows.length > 25 ? "" : " one"}">${cols}</div>
  <div class="ft">Times in TCT</div>
</div>
</body></html>`;
}
async function drawPost(chromium, s, t, nowS) {
  const browser = await chromium.launch();
  try {
    const page = await browser.newPage({ deviceScaleFactor: 2, viewport: { width: 800, height: 1200 } });
    await page.setContent(postPage(s, t, nowS), { waitUntil: "networkidle" });
    await page.evaluate(() => document.fonts.ready);
    const out = {};
    for (const name of Object.keys(POST_PICTURES)) out[name] = await page.locator(`#${name}`).screenshot({ omitBackground: true });
    return out;
  } finally {
    await browser.close();
  }
}

// tools/sig/job/main.ts
var site = (process.env.SITE ?? "").replace(/\/+$/, "");
var secret = process.env.SIG_JOB_SECRET ?? "";
if (!site || !secret) throw new Error("set SITE and SIG_JOB_SECRET");
var auth = { Authorization: `Bearer ${secret}` };
if (process.argv[2] === "post") await post();
else await sigs();
async function sigs() {
  const design = assets_hd_default.design ?? "";
  const res = await fetch(`${site}/sig/job/check?${new URLSearchParams({ design })}`, { method: "POST", headers: auth });
  if (!res.ok) throw new Error(`check: ${res.status} ${await res.text()}`);
  const { values, behind } = await res.json();
  console.log(`counts ${values.n} / ${values.week} / ${values.board}; behind: ${behind.join(", ") || "none"}`);
  for (const name of behind) {
    const gif = renderFrom(assets_hd_default.pieces, name, values);
    const q = new URLSearchParams({ n: String(values.n), week: String(values.week), board: String(values.board), design });
    const up = await fetch(`${site}/sig/job/${name}.gif?${q}`, { method: "PUT", headers: { ...auth, "Content-Type": "image/gif" }, body: gif });
    if (!up.ok) throw new Error(`${name}: ${up.status} ${await up.text()}`);
    console.log(`${name}: ${Math.round(gif.length / 1024)} KB uploaded`);
  }
}
async function post() {
  const [stats, terms] = await Promise.all(["/api/public/stats", "/api/public/terms"].map(async (p) => {
    const r = await fetch(site + p);
    if (!r.ok) throw new Error(`${p}: ${r.status}`);
    return r.json();
  }));
  const { chromium } = await import("playwright");
  const pics = await drawPost(chromium, stats, terms, Math.floor(Date.now() / 1e3));
  for (const [name, png] of Object.entries(pics)) {
    const up = await fetch(`${site}/post/job/${name}.png`, { method: "PUT", headers: { ...auth, "Content-Type": "image/png" }, body: png });
    if (!up.ok) throw new Error(`post ${name}: ${up.status} ${await up.text()}`);
    console.log(`post ${name}: ${Math.round(png.length / 1024)} KB, ${(await up.json()).changed ? "new" : "same"}`);
  }
}
